<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { auth } from '../lib/auth'
import { api } from '../lib/api'
import type { AgentNews, AgentNewsExecution, AppSettings, Product } from '../types'

const router=useRouter()
const agents = ref<AgentNews[]>([]), products = ref<Product[]>([])
const summary = reactive({ totalAgents: 0, activeAgents: 0, dataToday: 0, nextSchedule: null as string | null })
const modal = ref(false), step = ref(1), editingId = ref(''), toast = ref<{type:'success'|'error';message:string}|null>(null), loading = ref(true)
const search = ref(''), statusFilter = ref(''), platformFilter = ref(''), productFilter = ref(''), productOpen = ref(false)
const productSelect = ref<HTMLElement | null>(null)
const integrationSettings = ref<AppSettings | null>(null)
const termDraft = reactive({ general: '', instagram: '', tiktok: '', threads: '' })
const days = [{v:1,l:'Sen'},{v:2,l:'Sel'},{v:3,l:'Rab'},{v:4,l:'Kam'},{v:5,l:'Jum'},{v:6,l:'Sab'},{v:0,l:'Min'}]
const defaultForm = () => ({ name:'', description:'', status:'ACTIVE' as const, frequencyMinutes:60, imageMode:'single', imageCount:2, activeDays:[1,2,3,4,5], startTime:'08:00', endTime:'20:00', timezone:'Asia/Jakarta', generalKeywords:[] as string[], productIds:[] as string[], instagram:{enabled:true,hashtags:[] as string[],contentType:'posts',limit:50}, tiktok:{enabled:false,hashtags:[] as string[],limit:100,covers:false,subtitles:false,slideshows:false}, threads:{enabled:false,keywords:[] as string[],limit:50,sort:'RECENT'} })
const form = reactive(defaultForm())
const filteredAgents = computed(() => agents.value.filter((agent) => { const term=search.value.toLowerCase(); return (!term||[agent.name,agent.description,...agent.products.map(p=>p.name),...agent.generalKeywords].some(v=>v.toLowerCase().includes(term)))&&(!statusFilter.value||agent.status===statusFilter.value)&&(!productFilter.value||agent.productIds.includes(productFilter.value))&&(!platformFilter.value||agent.sources.some(s=>s.platform===platformFilter.value&&s.isEnabled)) }))
const filterProducts = computed(() => products.value.length ? products.value : [...new Map(
  agents.value.flatMap(agent => agent.products).map(product => [product.id, product]),
).values()])
const selectedProducts = computed(() => products.value.filter((product) => form.productIds.includes(product.id)))

function show(type:'success'|'error',message:string){toast.value={type,message};setTimeout(()=>{toast.value=null},5000)}
function addTerm(target:string[], key:keyof typeof termDraft){const value=termDraft[key].trim().replace(key==='instagram'||key==='tiktok'?/^#+/:'','');if(value&&!target.some(item=>item.toLowerCase()===value.toLowerCase()))target.push(value);termDraft[key]=''}
function removeTerm(target:string[],value:string){target.splice(target.indexOf(value),1)}
function resetForm(){Object.assign(form,defaultForm());editingId.value='';step.value=1;productOpen.value=false;modal.value=true}
function edit(agent:AgentNews){const source=(p:string)=>agent.sources.find(s=>s.platform===p);const ig=source('INSTAGRAM'),tt=source('TIKTOK'),th=source('THREADS');Object.assign(form,{name:agent.name,description:agent.description,status:agent.status,frequencyMinutes:agent.frequencyMinutes,imageMode:(agent.imageCount??1)>1?'carousel':'single',imageCount:Math.max(2,agent.imageCount??1),activeDays:[...agent.activeDays],startTime:agent.startTime,endTime:agent.endTime,timezone:agent.timezone,generalKeywords:[...agent.generalKeywords],productIds:[...agent.productIds],instagram:{enabled:ig?.isEnabled??false,hashtags:[...((ig?.config.hashtags as string[])??[])],contentType:ig?.config.contentType??'posts',limit:ig?.config.maxResultsPerHashtag??50},tiktok:{enabled:tt?.isEnabled??false,hashtags:[...((tt?.config.hashtags as string[])??[])],limit:tt?.config.totalVideos??100,covers:tt?.config.downloadCovers??false,subtitles:tt?.config.downloadSubtitles??false,slideshows:tt?.config.downloadSlideshows??false},threads:{enabled:th?.isEnabled??false,keywords:[...((th?.config.keywords as string[])??[])],limit:th?.config.maxItemsPerKeyword??50,sort:th?.config.sort??'RECENT'}});editingId.value=agent.id;step.value=1;modal.value=true}
function validateStep(){if(step.value===1&&(!form.name.trim()||!form.description.trim()))return 'Nama dan tujuan monitoring wajib diisi';if(step.value===2&&!form.productIds.length)return 'Minimal satu produk harus dipilih';if(step.value===3){if(!form.instagram.enabled&&!form.tiktok.enabled&&!form.threads.enabled)return 'Minimal satu sumber Apify harus aktif';if(form.instagram.enabled&&!form.instagram.hashtags.length)return 'Hashtag Instagram wajib diisi';if(form.tiktok.enabled&&!form.tiktok.hashtags.length)return 'Hashtag TikTok wajib diisi';if(form.threads.enabled&&!form.threads.keywords.length)return 'Keyword Threads wajib diisi'}return ''}
function next(){const error=validateStep();if(error){show('error',error);return}step.value=Math.min(4,step.value+1)}
function payload(){return{name:form.name,description:form.description,status:form.status,frequencyMinutes:Number(form.frequencyMinutes),imageCount:form.imageMode==='carousel'?Number(form.imageCount):1,activeDays:form.activeDays,startTime:form.startTime,endTime:form.endTime,timezone:form.timezone,generalKeywords:form.generalKeywords,productIds:form.productIds,sources:[{platform:'INSTAGRAM',actorId:'apify/instagram-hashtag-scraper',isEnabled:form.instagram.enabled,config:{hashtags:form.instagram.hashtags,contentType:form.instagram.contentType,maxResultsPerHashtag:Number(form.instagram.limit)}},{platform:'TIKTOK',actorId:'clockworks/tiktok-hashtag-scraper',isEnabled:form.tiktok.enabled,config:{hashtags:form.tiktok.hashtags,totalVideos:Number(form.tiktok.limit),downloadCovers:form.tiktok.covers,downloadSubtitles:form.tiktok.subtitles,downloadSlideshows:form.tiktok.slideshows}},{platform:'THREADS',actorId:'watcher.data/search-threads-by-keywords',isEnabled:form.threads.enabled,config:{keywords:form.threads.keywords,maxItemsPerKeyword:Number(form.threads.limit),sort:form.threads.sort}}]}}
async function load(){loading.value=true;try{const [news,productData,settingsData]=await Promise.all([api<{agents:AgentNews[];summary:typeof summary}>('/agent-news'),auth.canAccess('products') ? api<{products:Product[]}>('/products') : undefined, auth.canAccess('settings') ? api<{settings:AppSettings}>('/settings') : undefined]);agents.value=news.agents;Object.assign(summary,news.summary);products.value=productData?.products ?? [];integrationSettings.value=settingsData?.settings ?? null}catch(cause){show('error',cause instanceof Error?cause.message:'Gagal memuat Agent News')}finally{loading.value=false}}
async function save(){const error=validateStep();if(error){show('error',error);return}try{await api(editingId.value?`/agent-news/${editingId.value}`:'/agent-news',{method:editingId.value?'PATCH':'POST',body:JSON.stringify(payload())});modal.value=false;show('success',editingId.value?'Agent News berhasil diperbarui':'Agent News berhasil dibuat');await load()}catch(cause){show('error',cause instanceof Error?cause.message:'Gagal menyimpan Agent News')}}
async function run(agent:AgentNews){try{await api<{execution:AgentNewsExecution}>(`/agent-news/${agent.id}/run`,{method:'POST',body:'{}'});show('success',`${agent.name} masuk antrean monitoring`);await router.push(`/agent-news/${agent.id}?tab=history`)}catch(cause){show('error',cause instanceof Error?cause.message:'Get Now gagal')}}
async function toggle(agent:AgentNews){try{await api(`/agent-news/${agent.id}/status`,{method:'PATCH',body:JSON.stringify({status:agent.status==='ACTIVE'?'PAUSED':'ACTIVE'})});await load()}catch(cause){show('error',cause instanceof Error?cause.message:'Status gagal diubah')}}
async function remove(agent:AgentNews){if(!confirm(`Hapus agent ${agent.name}?`))return;try{await api(`/agent-news/${agent.id}`,{method:'DELETE'});show('success','Agent News dihapus');await load()}catch(cause){show('error',cause instanceof Error?cause.message:'Gagal menghapus agent')}}
const fmt=(value:string|null)=>value?new Intl.DateTimeFormat('id-ID',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Jakarta'}).format(new Date(value)):'-'
function closeProductDropdown(event: MouseEvent){if(productOpen.value&&!productSelect.value?.contains(event.target as Node))productOpen.value=false}
onMounted(()=>{document.addEventListener('click',closeProductDropdown);void load()})
onBeforeUnmount(()=>document.removeEventListener('click',closeProductDropdown))
</script>

<template>
  <Transition name="toast"><aside v-if="toast" :class="['news-toast',toast.type]" :role="toast.type==='error'?'alert':'status'">{{ toast.message }}</aside></Transition>
  <section class="news-page">
    <header class="news-header"><div><small>AI Agent</small><h1>♧ AI Content Intelligence</h1><p>Atur agent AI untuk memantau berita, tren, dan percakapan berdasarkan produk dan tag yang Anda tentukan.</p></div><button v-if="auth.isAdmin.value" class="create-btn" @click="resetForm">＋ Buat Agent Baru</button></header>
    <div class="summary-grid"><article><i>◇</i><span>Total Agent</span><strong>{{summary.totalAgents}}</strong></article><article><i>●</i><span>Agent Aktif</span><strong>{{summary.activeAgents}}</strong></article><article><i>▤</i><span>Total Data Hari Ini</span><strong>{{summary.dataToday}}</strong></article><article><i>◷</i><span>Jadwal Terdekat</span><strong>{{fmt(summary.nextSchedule)}}</strong></article></div>
    <div class="news-panel"><div class="filters"><input v-model="search" aria-label="Cari Agent News" placeholder="Cari agent, produk, atau keyword…"/><select v-model="productFilter" aria-label="Filter produk"><option value="">Semua produk</option><option v-for="p in filterProducts" :key="p.id" :value="p.id">{{p.name}}</option></select><select v-model="platformFilter" aria-label="Filter platform"><option value="">Semua platform</option><option>INSTAGRAM</option><option>TIKTOK</option><option>THREADS</option></select><select v-model="statusFilter" aria-label="Filter status"><option value="">Semua status</option><option value="ACTIVE">Aktif</option><option value="PAUSED">Nonaktif</option></select></div><p v-if="loading" class="empty">Memuat…</p><p v-else-if="!filteredAgents.length" class="empty">Belum ada Agent News.</p><div v-else class="table-scroll"><table><thead><tr><th>Agent</th><th>Produk</th><th>Sumber</th><th>Keyword / Tag</th><th>Status</th><th>Last Get</th><th>Jadwal Berikutnya</th><th>Aksi</th></tr></thead><tbody><tr v-for="agent in filteredAgents" :key="agent.id"><td><b>{{agent.name}}</b><small>{{agent.description}}</small></td><td><span v-for="p in agent.products" :key="p.id" class="pill">{{p.name}}</span></td><td><span v-for="s in agent.sources.filter(s=>s.isEnabled)" :key="s.platform" class="source-dot">{{s.platform}}</span></td><td>{{agent.generalKeywords.join(', ')||'-'}}</td><td><span :class="['status',agent.status.toLowerCase()]">{{agent.status==='ACTIVE'?'Aktif':'Nonaktif'}}</span></td><td>{{fmt(agent.lastSuccessAt)}}</td><td>{{fmt(agent.nextRunAt)}}</td><td><div class="actions"><button v-if="auth.isAdmin.value" :disabled="agent.status!=='ACTIVE'" :aria-label="`Get Now ${agent.name}`" data-tooltip="Get Now" @click="run(agent)">↻</button><button aria-label="Lihat hasil" data-tooltip="Lihat Hasil" @click="router.push(`/agent-news/${agent.id}?tab=monitoring`)">◉</button><button aria-label="Lihat riwayat" data-tooltip="Lihat Riwayat" @click="router.push(`/agent-news/${agent.id}?tab=history`)">◷</button><button v-if="auth.isAdmin.value" aria-label="Edit agent" data-tooltip="Edit Agent" @click="edit(agent)">✎</button><button v-if="auth.isAdmin.value" :class="{danger:agent.status==='ACTIVE'}" aria-label="Aktifkan atau nonaktifkan" :data-tooltip="agent.status==='ACTIVE'?'Stop Get Data':'Aktifkan Agent'" @click="toggle(agent)">{{agent.status==='ACTIVE'?'■':'▶'}}</button><button v-if="auth.isAdmin.value" class="danger" aria-label="Hapus agent" data-tooltip="Hapus Agent" @click="remove(agent)">♲</button></div></td></tr></tbody></table></div></div>
  </section>

  <div v-if="modal" class="modal-backdrop" role="dialog" aria-modal="true" aria-label="Buat Agent News Baru"><form class="wizard" @submit.prevent="save"><header><div class="bot">♧</div><div><h2>{{editingId?'Edit Agent News':'Buat Agent News Baru'}}</h2><p>Pilih produk, kata kunci, sumber Apify, dan jadwal monitoring.</p></div><button type="button" aria-label="Tutup" @click="modal=false">×</button></header><ol class="steps" aria-label="Tahapan pembuatan Agent News"><li v-for="(label,index) in ['Informasi','Produk & Keyword','Sumber Apify','Jadwal & Konfirmasi']" :key="label" :class="{active:step===index+1,done:step>index+1}" :aria-current="step===index+1?'step':undefined"><b>{{index+1}}</b><span>{{label}}</span></li></ol>
      <main>
        <section v-if="step===1" class="step-pane"><label>Nama Agent *<input v-model.trim="form.name" aria-label="Nama Agent" placeholder="AceKid Trend Monitor" required/></label><label>Tujuan Monitoring *<textarea v-model.trim="form.description" aria-label="Tujuan Monitoring" rows="5" placeholder="Memantau tren, hashtag, dan percakapan terkait nutrisi anak." required></textarea></label><label class="toggle-row">Status Agent <input v-model="form.status" type="checkbox" true-value="ACTIVE" false-value="PAUSED"/><span></span><b>{{form.status==='ACTIVE'?'Aktif':'Dijeda'}}</b></label></section>
        <section v-else-if="step===2" class="step-pane"><div class="field"><b>Produk yang Dipantau *</b><div ref="productSelect" class="product-select"><button type="button" aria-label="Pilih produk" :aria-expanded="productOpen" @click="productOpen=!productOpen"><span class="selection-preview"><span v-if="selectedProducts.length" class="selection-avatars"><img v-for="p in selectedProducts.slice(0,3)" :key="p.id" :src="p.productImage" alt=""/></span><span><strong>{{selectedProducts.length?`${selectedProducts.length} produk dipilih`:'Pilih produk'}}</strong><small>{{selectedProducts.length?selectedProducts.map(p=>p.name).join(', '):'Pilih satu atau beberapa produk'}}</small></span></span><i aria-hidden="true">⌄</i></button><div v-if="productOpen" class="product-options"><p>{{products.length}} produk tersedia</p><label v-for="p in products" :key="p.id" :class="{selected:form.productIds.includes(p.id)}"><input v-model="form.productIds" type="checkbox" :value="p.id" :aria-label="p.name"/><img :src="p.productImage" :alt="p.name"/><span><strong>{{p.name}}</strong><small>{{p.productType}}</small></span><i>{{form.productIds.includes(p.id)?'✓':''}}</i></label></div></div><div class="chips"><span v-for="p in selectedProducts" :key="p.id">{{p.name}}</span></div></div><div class="field"><b>Keyword / Tag Umum <small>(opsional)</small></b><div class="tag-entry"><input v-model="termDraft.general" aria-label="Keyword umum" placeholder="#AceKid atau Nutrisi Anak" @keydown.enter.prevent="addTerm(form.generalKeywords,'general')"/><button type="button" @click="addTerm(form.generalKeywords,'general')">Tambah</button></div><div class="chips"><span v-for="term in form.generalKeywords" :key="term">{{term}} <button type="button" @click="removeTerm(form.generalKeywords,term)">×</button></span></div></div></section>
        <section v-else-if="step===3" class="source-list"><aside class="settings-source"><div><strong>Konfigurasi Integrasi</strong><p>LLM, Tebar API, dan Apify API dikelola terpusat melalui menu Synchronize.</p></div><div class="integration-state"><span :class="{ready:integrationSettings?.llm.apiKeyConfigured}">LLM {{integrationSettings?.llm.apiKeyConfigured?'Siap':'Belum siap'}}</span><span :class="{ready:integrationSettings?.tebar.apiKeyConfigured}">Tebar {{integrationSettings?.tebar.apiKeyConfigured?'Siap':'Belum siap'}}</span><span :class="{ready:integrationSettings?.apify.apiTokenConfigured}">Apify {{integrationSettings?.apify.apiTokenConfigured?'Siap':'Belum siap'}}</span><RouterLink to="/settings">Buka Synchronize</RouterLink></div></aside><article :class="{disabled:!form.instagram.enabled}"><header><label class="source-toggle"><input v-model="form.instagram.enabled" type="checkbox" aria-label="Aktifkan Instagram"/><span></span><b>{{form.instagram.enabled?'Aktif':'Nonaktif'}}</b></label><div><h3>Instagram Hashtag Scraper</h3><code>apify/instagram-hashtag-scraper</code></div></header><div class="source-fields"><div class="field"><b>Hashtag Instagram</b><div class="tag-entry"><input v-model="termDraft.instagram" aria-label="Hashtag Instagram" :disabled="!form.instagram.enabled" @keydown.enter.prevent="addTerm(form.instagram.hashtags,'instagram')"/><button type="button" aria-label="Tambah hashtag Instagram" :disabled="!form.instagram.enabled" @click="addTerm(form.instagram.hashtags,'instagram')">Tambah</button></div><div class="chips"><span v-for="term in form.instagram.hashtags" :key="term">#{{term}} <button type="button" @click="removeTerm(form.instagram.hashtags,term)">×</button></span></div></div><label>Jenis Konten<span class="select-control"><select v-model="form.instagram.contentType" :disabled="!form.instagram.enabled"><option value="posts">Posting</option><option value="reels">Reels</option></select></span></label><label>Maks. hasil per hashtag<input v-model.number="form.instagram.limit" type="number" min="1" max="1000" :disabled="!form.instagram.enabled"/></label></div></article>
          <article :class="{disabled:!form.tiktok.enabled}"><header><label class="source-toggle"><input v-model="form.tiktok.enabled" type="checkbox" aria-label="Aktifkan TikTok"/><span></span><b>{{form.tiktok.enabled?'Aktif':'Nonaktif'}}</b></label><div><h3>TikTok Hashtag Scraper</h3><code>clockworks/tiktok-hashtag-scraper</code></div></header><div class="source-fields"><div class="field"><b>Hashtag TikTok</b><div class="tag-entry"><input v-model="termDraft.tiktok" :disabled="!form.tiktok.enabled" @keydown.enter.prevent="addTerm(form.tiktok.hashtags,'tiktok')"/><button type="button" :disabled="!form.tiktok.enabled" @click="addTerm(form.tiktok.hashtags,'tiktok')">Tambah</button></div><div class="chips"><span v-for="term in form.tiktok.hashtags" :key="term">#{{term}}</span></div></div><label>Total Video yang Diambil<input v-model.number="form.tiktok.limit" type="number" min="1" max="800" :disabled="!form.tiktok.enabled"/><small>Jumlah dibagi ke seluruh hashtag.</small></label><div class="checks"><label><input v-model="form.tiktok.covers" type="checkbox" :disabled="!form.tiktok.enabled"/> Unduh thumbnail</label><label><input v-model="form.tiktok.subtitles" type="checkbox" :disabled="!form.tiktok.enabled"/> Unduh subtitle</label><label><input v-model="form.tiktok.slideshows" type="checkbox" :disabled="!form.tiktok.enabled"/> Unduh slideshow</label></div></div></article>
          <article :class="{disabled:!form.threads.enabled}"><header><label class="source-toggle"><input v-model="form.threads.enabled" type="checkbox" aria-label="Aktifkan Threads"/><span></span><b>{{form.threads.enabled?'Aktif':'Nonaktif'}}</b></label><div><h3>Threads Keyword Search</h3><code>watcher.data/search-threads-by-keywords</code></div></header><div class="source-fields"><div class="field"><b>Keyword / Frasa Threads</b><div class="tag-entry"><input v-model="termDraft.threads" :disabled="!form.threads.enabled" @keydown.enter.prevent="addTerm(form.threads.keywords,'threads')"/><button type="button" :disabled="!form.threads.enabled" @click="addTerm(form.threads.keywords,'threads')">Tambah</button></div><div class="chips"><span v-for="term in form.threads.keywords" :key="term">{{term}}</span></div></div><label>Maks. item per keyword<input v-model.number="form.threads.limit" type="number" min="1" max="2000" :disabled="!form.threads.enabled"/></label><label>Urutan<select v-model="form.threads.sort" :disabled="!form.threads.enabled"><option value="RECENT">Terbaru</option><option value="RELEVANT">Relevan</option></select></label></div></article></section>
        <section v-else class="confirm-grid"><div class="schedule-card"><h3>Jadwal Monitoring</h3><label>Format Konten Otomatis<select v-model="form.imageMode"><option value="single">Single Post</option><option value="carousel">Carousel</option></select></label><label v-if="form.imageMode==='carousel'">Jumlah gambar<select v-model.number="form.imageCount"><option v-for="count in [2,3,4,5]" :key="count" :value="count">{{count}}</option></select></label><label>Frekuensi<select v-model.number="form.frequencyMinutes"><option :value="15">Setiap 15 menit</option><option :value="30">Setiap 30 menit</option><option :value="60">Setiap 1 jam</option><option :value="180">Setiap 3 jam</option><option :value="360">Setiap 6 jam</option><option :value="720">Setiap 12 jam</option><option :value="1440">Setiap 24 jam</option></select></label><fieldset><legend>Hari Aktif</legend><label v-for="d in days" :key="d.v"><input v-model="form.activeDays" type="checkbox" :value="d.v"/>{{d.l}}</label></fieldset><div class="time-row"><label>Jam Mulai<input v-model="form.startTime" type="time"/></label><label>Jam Selesai<input v-model="form.endTime" type="time"/></label></div><label>Zona Waktu<select v-model="form.timezone"><option>Asia/Jakarta</option><option>Asia/Makassar</option><option>Asia/Jayapura</option></select></label></div><aside class="review"><h3>Ringkasan Agent</h3><dl><dt>Nama Agent</dt><dd>{{form.name}}</dd><dt>Produk</dt><dd>{{selectedProducts.map(p=>p.name).join(', ')}}</dd><dt>Sumber Aktif</dt><dd>{{[form.instagram.enabled?'Instagram':'',form.tiktok.enabled?'TikTok':'',form.threads.enabled?'Threads':''].filter(Boolean).join(', ')}}</dd><dt>Jadwal</dt><dd>{{form.frequencyMinutes}} menit, {{form.startTime}}–{{form.endTime}}</dd><dt>Rentang Data</dt><dd>Posting {{form.frequencyMinutes}} menit terakhir</dd><dt>Analisis AI</dt><dd>Brand Profile + Tujuan Monitoring</dd><dt>Status</dt><dd>{{form.status==='ACTIVE'?'Aktif':'Dijeda'}}</dd></dl><p>ⓘ Menggunakan API Token Apify dan LLM dari menu Synchronize.</p></aside></section>
      </main><footer><button type="button" class="cancel" @click="modal=false">Batal</button><button v-if="step>1" type="button" class="back" @click="step--">← Kembali</button><button v-if="step<4" type="button" class="next" @click="next">Lanjut</button><button v-else type="submit" class="next">＋ {{editingId?'Simpan Perubahan':'Buat Agent'}}</button></footer></form></div>
</template>

